#include <stdio.h>
#include <math.h>
double Lx=1,Ly=1,Lz=1;
int main(){
 FILE*f=fopen("reconstructed.ppm","w");
 fprintf(f,"P3\n2400 1800\n255\n");
 double n=sqrt(Lx*Lx+Ly*Ly+Lz*Lz);double lx=Lx/n,ly=Ly/n,lz=Lz/n;
 for(int j=0;j<1800;j++)for(int i=0;i<2400;i++){
  double dx=(i-1200+.5)/900,dy=(900-j-.5)/900,dz=1,m=sqrt(dx*dx+dy*dy+1);
  dx/=m;dy/=m;dz/=m;
  double c[3];
  // sphere
  double ox=0,oy=.5,oz=-5; // center rel camera... oc = origin-center
  double ocx=0,ocy=.5,ocz=-5;
  double b=ocx*dx+ocy*dy+ocz*dz,cc=ocx*ocx+ocy*ocy+ocz*ocz-1,d=b*b-cc;
  int hit=0;
  if(d>0&&(-b-sqrt(d))>0){
   double t=-b-sqrt(d);
   double nx=ocx+t*dx,ny=ocy+t*dy,nz=ocz+t*dz;
   double s=nx*lx+ny*ly+nz*lz;if(s<0)s=0;
   // sphere shadow irrelevant
   double k=.2+.8*s;c[0]=255*k;c[1]=50*k;c[2]=50*k;hit=1;
  }
  if(!hit&&dy<0){
   double t=-1.5/dy,x=t*dx,z=t*dz;
   double g=((int)floor(x)+(int)floor(z))&1?152:67;
   // shadow
   double px=x,py=-1.5,pz=z;
   double qx=px,qy=py+.5,qz=pz-5;
   double bb=qx*lx+qy*ly+qz*lz,dd=bb*bb-(qx*qx+qy*qy+qz*qz-1);
   if(dd>0&&bb<0)g*=.3;
   c[0]=c[1]=c[2]=g;hit=1;
  }
  if(!hit){double t=dy;c[0]=192-65*t;c[1]=217-38.5*t;c[2]=255;}
  fprintf(f,"%d %d %d\n",(int)c[0],(int)c[1],(int)c[2]);
 }
}
